import pandas as pd,numpy as np
from scipy.stats import spearmanr
syms=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
P={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date').close for s in syms}; px=pd.DataFrame(P).sort_index(); r=px.pct_change()
# defensive sensitivity: rolling 60d beta to VIX daily pct change; lower beta (resilience) ranked higher
v=pd.read_csv('../persistent/index_data/VIX.csv',parse_dates=['date']).set_index('date').close.reindex(px.index).ffill(); vr=v.pct_change()
f=r.rolling(60).cov(vr).div(vr.rolling(60).var(),axis=0)*-1
for h in [1,5,10]:
 y=px.pct_change(h).shift(-h); z=[]; ns=[]
 for d in f.index:
  ok=f.loc[d].notna()&y.loc[d].notna()
  if ok.sum()>=8:z.append(spearmanr(f.loc[d,ok],y.loc[d,ok]).statistic);ns.append(ok.sum())
 z=pd.Series(z).dropna(); print('h',h,'dates',len(z),'avgN',round(np.mean(ns),2),'IC',round(z.mean(),6),'ICIR',round(z.mean()/z.std(ddof=1),6),'hit',round((z>0).mean(),4))
print('turnover',f.rank(axis=1,pct=True).diff().abs().mean().mean(),'coverage',f.notna().sum(axis=1).mean()/15)
for a,b in [(0,907),(907,1814)]:
 z=[]; y=px.pct_change(1).shift(-1)
 for d in f.index[a:b]:
  ok=f.loc[d].notna()&y.loc[d].notna()
  if ok.sum()>=8:z.append(spearmanr(f.loc[d,ok],y.loc[d,ok]).statistic)
 z=pd.Series(z);print('segment',a,len(z),z.mean(),z.mean()/z.std(ddof=1))

import pandas as pd, numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def load(sym, macro=False):
 p=('../persistent/index_data/' if macro else '../persistent/stock_data/')+sym+'.csv'; d=pd.read_csv(p); d.date=pd.to_datetime(d.date); return d.set_index('date').close
px=pd.concat({s:load(s) for s in U},axis=1).sort_index(); r=px.pct_change()
m=pd.concat({'vix':load('VIX',1).pct_change(),'dxy':load('DXY',1).pct_change(),'us10':load('US10Y').pct_change()},axis=1).reindex(px.index).ffill()
z=(m-m.rolling(60,min_periods=40).mean())/m.rolling(60,min_periods=40).std(); shock=(z.vix+z.dxy-z.us10)/3
beta=pd.DataFrame(index=px.index,columns=U,dtype=float)
for s in U: beta[s]=r[s].rolling(60,min_periods=40).cov(shock)/shock.rolling(60,min_periods=40).var()
fac=-beta
for h in [1,5,10]:
 a=[]; ns=[]
 for i in range(len(px)-h):
  q=pd.concat([fac.iloc[i],px.iloc[i+h]/px.iloc[i]-1],axis=1).dropna()
  if len(q)>=8:a.append(spearmanr(q.iloc[:,0],q.iloc[:,1]).statistic);ns.append(len(q))
 a=np.array(a);print('macro_resilience',h,'dates',len(a),'avgN',np.mean(ns),'IC',a.mean(),'ICIR',a.mean()/a.std(),'hit',(a>0).mean())
rev=-r.rolling(5).sum(); bs=(beta.sub(beta.mean(axis=1),axis=0)).div(beta.std(axis=1),axis=0)
fac2=rev*(1+0.35*shock.abs().values[:,None]*(-bs))
for h in [1,5,10]:
 a=[]
 for i in range(len(px)-h):
  q=pd.concat([fac2.iloc[i],px.iloc[i+h]/px.iloc[i]-1],axis=1).dropna()
  if len(q)>=8:a.append(spearmanr(q.iloc[:,0],q.iloc[:,1]).statistic)
 a=np.array(a);print('conditional_rev',h,'dates',len(a),'IC',a.mean(),'ICIR',a.mean()/a.std(),'hit',(a>0).mean())

# append sensitivity of macro-conditioned reversal
exec(open('scripts/miner_2_20260716_macro_impulse.py').read().split("for h in [1,5,10]:\n a=[]\n for i in range(len(px)-h):\n  q=pd.concat([fac2")[0])
for c in [0.5,1.0,2.0]:
 f=rev*(1+c*shock.abs().values[:,None]*(-bs)); a=[]
 for i in range(len(px)-1):
  q=pd.concat([f.iloc[i],px.iloc[i+1]/px.iloc[i]-1],axis=1).dropna()
  if len(q)>=8:a.append(spearmanr(q.iloc[:,0],q.iloc[:,1]).statistic)
 a=np.array(a); print('conditional_rev_c',c,'dates',len(a),'IC',a.mean(),'ICIR',a.mean()/a.std(),'hit',(a>0).mean())

import pandas as pd,numpy as np,os
