import pandas as pd,numpy as np
from pathlib import Path
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; end=pd.Timestamp('2026-07-15')
D={s:pd.read_csv(Path('../persistent/stock_data')/(s+'.csv'),parse_dates=['date']).set_index('date').sort_index().loc[:end] for s in U}
# downside asymmetry: positive reward relative to downside variation; robust 20d rolling downside/upside mean ratio
R=pd.concat({s:D[s].close.pct_change() for s in U},axis=1)
# higher means less downside / more upside; all trailing data only
up=R.clip(lower=0).rolling(20,min_periods=15).mean()
dn=(-R.clip(upper=0)).rolling(20,min_periods=15).mean()
F=(up/(dn+1e-8)).replace([np.inf,-np.inf],np.nan)
# evaluate forward returns at next valid observation
for h in [1,5,10]:
  ics=[]; ns=[]; yrs={}
  for dt in F.index:
    xs=[];ys=[]
    for s in U:
      if dt not in D[s].index or pd.isna(F.loc[dt,s]): continue
      ix=D[s].index.get_loc(dt); j=ix+h
      if j<len(D[s]) and pd.notna(D[s].close.iloc[j]): xs.append(F.loc[dt,s]);ys.append(D[s].close.iloc[j]/D[s].close.iloc[ix]-1)
    if len(xs)>=8 and len(set(xs))>1:
      ics.append(spearmanr(xs,ys).statistic); ns.append(len(xs)); yrs.setdefault(str(dt.year),[]).append(ics[-1])
  a=np.array(ics); print('h',h,'N',len(a),'meanN',round(np.mean(ns),2),'IC',round(a.mean(),5),'ICIR',round(a.mean()/a.std(ddof=1),5),'hit',round(np.mean(a>0),4),'years',{k:round(np.mean(x),4) for k,x in yrs.items()})
print('coverage',round(np.mean(F.notna().sum(axis=1)/15),4),'turnover',round(F.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean()*2,4))
for n,p in [('rev5',-R.rolling(5).sum()),('mom20',R.rolling(20).sum()),('clv',pd.concat({s:(D[s].close-D[s].low)/(D[s].high-D[s].low+1e-12) for s in U},axis=1))]: print('corr',n,F.stack().corr(p.stack()))

